from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import OrganizationTeam, User
from .serializers import TeamSerializer
from .permissions import IsOrgAdmin

class TeamViewSet(viewsets.ModelViewSet):
    serializer_class = TeamSerializer

    def get_queryset(self):
        return OrganizationTeam.objects.filter(organization=self.request.user.organization)

    def get_permissions(self):
        if self.action in ['create', 'update', 'partial_update', 'destroy', 'add_member']:
            return [permissions.IsAuthenticated(), IsOrgAdmin()]
        return [permissions.IsAuthenticated()]

    @action(detail=True, methods=['post'])
    def add_member(self, request, pk=None):
        team = self.get_object()
        user_id = request.data.get('user_id')
        user = User.objects.get(id=user_id, organization=request.user.organization)
        team.members.add(user)
        return Response({'status': 'member added'})
